export const EXPANDED_QUESTIONS=rows.trim().split('\n').filter(line=>!line.endsWith('|REMOVE')).map(line=>{
 const [id,category,prompt,ref,scope,hint,answerText,note]=line.split('|');
 if(!note)throw Error('Incomplete Biblillion content row: '+id);
 const answers=answerText.split(';').map(value=>{const [name,points,aliases='']=value.split(':');return {name,points:Number(points),ref,note,aliases:aliases?aliases.split(','):[]};});
 return {id,category,prompt,scope:`${scope} Read ${ref}.`,hint,answers};
});
